fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Preallocate a vector with the same length as the input
    let mut new_list = Vec::with_capacity(list.len());

    // Append elements from index n to the end
    new_list.extend_from_slice(&list[n..]);

    // Append elements from the start up to index n (exclusive)
    new_list.extend_from_slice(&list[..n]);

    new_list
}